begin; create extension if not exists pgtap with schema extensions; select plan(14);
select ok(exists(select 1 from public.role_template_permissions where template_key='teacher' and permission_key='assignments.publish'),'teacher template publishes assignments');
insert into public.schools(id,name) values('61000000-0000-4000-8000-000000000001','Learning A'),('62000000-0000-4000-8000-000000000002','Learning B');
insert into auth.users(id,email,aud,role) values
('6a000000-0000-4000-8000-000000000002','learn-teacher-a@test.invalid','authenticated','authenticated'),('6a000000-0000-4000-8000-000000000003','learn-student-a@test.invalid','authenticated','authenticated'),('6a000000-0000-4000-8000-000000000004','learn-student2-a@test.invalid','authenticated','authenticated'),
('6b000000-0000-4000-8000-000000000002','learn-teacher-b@test.invalid','authenticated','authenticated'),('6b000000-0000-4000-8000-000000000003','learn-student-b@test.invalid','authenticated','authenticated');
update public.profiles set school_id='61000000-0000-4000-8000-000000000001',role=case when email like '%teacher%' then 'teacher'::public.profile_role else 'student'::public.profile_role end where email like 'learn-%-a@test.invalid';
update public.profiles set school_id='62000000-0000-4000-8000-000000000002',role=case when email like '%teacher%' then 'teacher'::public.profile_role else 'student'::public.profile_role end where email like 'learn-%-b@test.invalid';
insert into public.role_permissions(role_id,permission_key,scope) select r.id,p.key,'assigned' from public.school_roles r cross join public.permission_definitions p where r.school_id in('61000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000002') and r.legacy_key='teacher' and p.key in('assignments.view','assignments.create','assignments.update','assignments.publish','students.view','classes.view') on conflict(role_id,permission_key) do update set scope=excluded.scope;
insert into public.profile_role_assignments(profile_id,role_id,is_primary) select p.id,r.id,true from public.profiles p join public.school_roles r on r.school_id=p.school_id and r.legacy_key=case when p.role='teacher' then 'teacher' else 'student' end where p.email like 'learn-%' on conflict do nothing;
insert into public.school_years(id,school_id,name,starts_on,ends_on,is_current) values('61100000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','2026 A','2026-08-01','2027-07-31',true),('62100000-0000-4000-8000-000000000002','62000000-0000-4000-8000-000000000002','2026 B','2026-08-01','2027-07-31',true);
insert into public.subjects(id,school_id,name,code) values('61200000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','Biologie','BIO'),('62200000-0000-4000-8000-000000000002','62000000-0000-4000-8000-000000000002','Techniek','TEC');
insert into public.teaching_groups(id,school_id,school_year_id,subject_id,name) values('61300000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','61100000-0000-4000-8000-000000000001','61200000-0000-4000-8000-000000000001','Groep A'),('62300000-0000-4000-8000-000000000002','62000000-0000-4000-8000-000000000002','62100000-0000-4000-8000-000000000002','62200000-0000-4000-8000-000000000002','Groep B');
insert into public.teacher_group_assignments(school_id,teacher_profile_id,teaching_group_id) values('61000000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000002','61300000-0000-4000-8000-000000000001'),('62000000-0000-4000-8000-000000000002','6b000000-0000-4000-8000-000000000002','62300000-0000-4000-8000-000000000002');
insert into public.student_group_memberships(school_id,student_profile_id,teaching_group_id,status) values('61000000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000003','61300000-0000-4000-8000-000000000001','active'),('61000000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000004','61300000-0000-4000-8000-000000000001','active'),('62000000-0000-4000-8000-000000000002','6b000000-0000-4000-8000-000000000003','62300000-0000-4000-8000-000000000002','active');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"6a000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$insert into public.assignments(id,school_id,teaching_group_id,subject_id,title,status,created_by) values('61500000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','61300000-0000-4000-8000-000000000001','61200000-0000-4000-8000-000000000001','Opdracht A','published','6a000000-0000-4000-8000-000000000002')$$,'teacher publishes assigned assignment');
select lives_ok($$insert into public.assignments(id,school_id,teaching_group_id,subject_id,title,status,created_by) values('61500000-0000-4000-8000-000000000002','61000000-0000-4000-8000-000000000001','61300000-0000-4000-8000-000000000001','61200000-0000-4000-8000-000000000001','Concept A','draft','6a000000-0000-4000-8000-000000000002')$$,'teacher saves draft assignment');
select throws_like($$insert into public.assignments(school_id,teaching_group_id,subject_id,title,status,created_by) values('62000000-0000-4000-8000-000000000002','62300000-0000-4000-8000-000000000002','62200000-0000-4000-8000-000000000002','B opdracht','published','6a000000-0000-4000-8000-000000000002')$$,'%maker%','teacher cannot create School B assignment');
select set_config('request.jwt.claims','{"sub":"6a000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*) from public.assignments),1::bigint,'student sees published assignment only');
select lives_ok($$insert into public.assignment_submissions(id,school_id,assignment_id,student_profile_id,body,status) values('61600000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','61500000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000003','Mijn werk','submitted')$$,'student submits own work');
select throws_like($$insert into public.assignment_submissions(school_id,assignment_id,student_profile_id,body,status) values('61000000-0000-4000-8000-000000000001','61500000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000003','Dubbel','submitted')$$,'%duplicate key%','one submission per assignment student');
select throws_like($$insert into public.assignment_submissions(school_id,assignment_id,student_profile_id,body,status) values('61000000-0000-4000-8000-000000000001','61500000-0000-4000-8000-000000000001','6b000000-0000-4000-8000-000000000003','Cross','submitted')$$,'%leerling%','cross-school submission rejected');
select throws_like($$insert into public.file_assets(id,school_id,owner_id,bucket,storage_path,file_name,visibility,related_type,related_id,scan_status) values('61700000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000003','school-files','610/a/submissions/x.txt','x.txt','private','assignment_submission','61600000-0000-4000-8000-000000000001','pending')$$,'%row-level security%','student cannot register a file while uploads are disabled');
select set_config('request.jwt.claims','{"sub":"6a000000-0000-4000-8000-000000000004","role":"authenticated"}',true); select is((select count(*) from public.assignment_submissions),0::bigint,'other student cannot see submission');
select set_config('request.jwt.claims','{"sub":"6a000000-0000-4000-8000-000000000002","role":"authenticated"}',true); select is((select count(*) from public.assignment_submissions),1::bigint,'assigned teacher sees submission'); select is((select count(*) from public.file_assets),0::bigint,'pending file is not shared with teacher');
select lives_ok($$update public.assignment_submissions set status='accepted',feedback='Goed',reviewed_by='6a000000-0000-4000-8000-000000000002',reviewed_at=now() where id='61600000-0000-4000-8000-000000000001'$$,'teacher reviews assigned submission');
select set_config('request.jwt.claims','{"sub":"6b000000-0000-4000-8000-000000000002","role":"authenticated"}',true); select is((select count(*) from public.assignments where school_id='61000000-0000-4000-8000-000000000001'),0::bigint,'School B teacher cannot read School A learning');
reset role; select * from finish(); rollback;
